contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(dummy >= 0);
        uint balBefore = address(c).balance;
        uint cntBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint myBefore = address(this).balance;
        c.withdraw(0); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore && c.depositsCount() == cntBefore && address(this).balance == myBefore);
    }
    receive() external payable {}
}

