// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 dummy) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dummy >= 0);
        uint balBefore = address(c).balance;
        uint256 cntBefore;
        try c.depositsCount() returns (uint256 __r) { cntBefore = __r; } catch { return; }
        uint myBefore = address(this).balance;
        try c.withdraw(0) {} catch { return; }
        assertTrue(address(c).balance == balBefore && c.depositsCount() == cntBefore && address(this).balance == myBefore);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
